            aOrbiterJ = (((aWandererJ + RotL64(aScatter, 5U)) + RotL64(aCarry, 27U)) + 0x2861E93CF7270888ULL) + aOASaltA[(((511U - aIndex) + 461U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 57U)) + 0x69C0E79B7938DA83ULL) + aOASaltH[(((511U - aIndex) + 407U)) & S_SALT1];
