            aWandererJ = aWandererJ + ((((RotL64(aCross, 19U) + aOrbiterJ) + RotL64(aOrbiterH, 23U)) + RotL64(aCarry, 47U)) + aNonceWordI);
            aWandererG = aWandererG ^ (((RotL64(aIngress, 5U) + aOrbiterH) + RotL64(aOrbiterB, 53U)) + aNonceWordA);
            aWandererB = aWandererB + (((RotL64(aScatter, 46U) + aOrbiterD) + RotL64(aOrbiterI, 60U)) + aWUSaltD[(((511U - aIndex) + 260U)) & S_SALT1]);
            //
