            aOrbiterC = (((aWandererA + RotL64(aIngress, 53U)) + 0xBA685711A220E32FULL) + aOASaltF[(((511U - aIndex) + 317U)) & S_SALT1]) + aNonceWordA;
            aOrbiterA = ((aWandererI + RotL64(aScatter, 23U)) + 0x1E735693B8C9331CULL) + aOASaltD[((aIndex + 18U)) & S_SALT1];
