            aWandererF = aWandererF + ((((RotL64(aPrevious, 29U) + RotL64(aOrbiterG, 34U)) + aOrbiterF) + aNonceWordL) + aWUSaltD[(((511U - aIndex) + 495U)) & S_SALT1]);
