            aOrbiterB = ((aWandererA + RotL64(aIngress, 57U)) + 0x73018CEA90A9EF4CULL) + aOASaltB[((aIndex + 87U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aScatter, 37U)) + 0xD87035CC25A2F7B8ULL;
            aOrbiterJ = (((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 53U)) + 0xCE7A487E9ECECF79ULL) + aOASaltE[(((511U - aIndex) + 208U)) & S_SALT1];
            aOrbiterC = (aWandererE + RotL64(aCross, 53U)) + 0x6F07963CA73D9171ULL;
