            aOrbiterD = (aWandererC + RotL64(aScatter, 6U)) + 0x758DE574DB6A2128ULL;
            aOrbiterG = (((aWandererB + RotL64(aPrevious, 21U)) + RotL64(aCarry, 39U)) + 0xB1192C69B43CBDE4ULL) + aOASaltF[((aIndex + 175U)) & S_SALT1];
