            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x415A62F8B5338981ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x7F3E96F7351DD074ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA9FD0BBB5301EA59ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0xA4278A4792CC5DAFULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x473ACFB8991B4A4CULL) ^ aOUSaltD[((aIndex + 458U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x59435DF8A4BCA149ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x2D5911D84D4E10E3ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x22E27273179EE5D3ULL) ^ aOUSaltB[((aIndex + 206U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x45CC54C6878CBBCFULL), 23U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x61E97BDC56FA3F07ULL;
